class PlayersController < ApplicationController
  #all of this besides index and import is auto generated by rails
  
  before_action :set_player, only: %i[ show edit update destroy ]
  skip_forgery_protection only: [:import]
  # GET /players or /players.json
 def index
  search = params[:search].to_s.strip
  @players = search.present? ? Player.where(player_id: search) : Player.all
end

  # GET /players/1 or /players/1.json
  def show
  end

  # GET /players/new
  def new
    @player = Player.new
  end

  # GET /players/1/edit
  def edit
  end

  # POST /players or /players.json
  def create
    @player = Player.new(player_params)

    respond_to do |format|
      if @player.save
        format.html { redirect_to @player, notice: "Player was successfully created." }
        format.json { render :show, status: :created, location: @player }
      else
        format.html { render :new, status: :unprocessable_content }
        format.json { render json: @player.errors, status: :unprocessable_content }
      end
    end
  end

  # PATCH/PUT /players/1 or /players/1.json
  def update
    respond_to do |format|
      if @player.update(player_params)
        format.html { redirect_to @player, notice: "Player was successfully updated.", status: :see_other }
        format.json { render :show, status: :ok, location: @player }
      else
        format.html { render :edit, status: :unprocessable_content }
        format.json { render json: @player.errors, status: :unprocessable_content }
      end
    end
  end

  # DELETE /players/1 or /players/1.json
  def destroy
    @player.destroy!

    respond_to do |format|
      format.html { redirect_to players_path, notice: "Player was successfully destroyed.", status: :see_other }
      format.json { head :no_content }
    end
  end

def import
  file = params[:file]
  
  if file.blank?
    return render json: { 
      error: "Please choose an Excel file."
      }, status: :unprocessable_entity
     end
      
begin
  sheet = Roo::Excelx.new(file.tempfile.path).sheet("Master")
  count = 0

  Player.transaction do #makes sure that all rows are imported at once
    (2..sheet.last_row.to_i).each do |i|
      id = sheet.cell(i, 1)
      next if id.blank?
      salary = sheet.cell(i, 30)
      player = Player.find_or_initialize_by(player_id: id.to_i.to_s) #this makes it so I don't get conflicting player IDs
      player.update!(
        name: sheet.cell(i, 2),
        salary: salary.is_a?(Numeric) ? salary.to_i : nil #because there are empty salaries this saves the N/A ones as nil but puts the others as ints so we can use them in salary calculation later
      )

      count += 1
    end
  end

  render json: {
     message: "Imported #{count} player rows.",
     count: count
     }, status: :ok
    
    rescue StandardError => e
      Rails.logger.error(
         "Player import failed: #{e.class}: #{e.message}"
         )
      
      render json: {
        error: "Import failed. Check the Rails logs for details."
        }, status: :unprocessable_entity
    end
end

  private
    # Use callbacks to share common setup or constraints between actions.
    def set_player
      @player = Player.find(params.expect(:id))
    end

    # Only allow a list of trusted parameters through.
    def player_params
      params.expect(player: [ :player_id, :name, :salary ])
    end
end
